use sha2::{Digest, Sha256};
use std::{hint::black_box, time::Instant};
fn main() {
    let data = vec![81u8; 8 * 1024 * 1024];
    let mut samples = Vec::new();
    for iteration in 0..22 {
        let start = Instant::now();
        let mut hash = Sha256::new();
        for chunk in data.chunks(64 * 1024) { hash.update(black_box(chunk)); }
        let result = format!("{:x}", hash.finalize());
        let ms = start.elapsed().as_secs_f64() * 1000.0;
        assert_eq!(result, "b4dc7b26baa48d0e780658b929d8fc269bde6220208833724e0a8d6a8deb490b");
        if iteration >= 2 { samples.push(ms); }
    }
    println!("{{\"accelerated\":{},\"bytes\":{},\"chunkBytes\":65536,\"samplesMs\":{:?}}}", cfg!(feature="accelerated"), data.len(), samples);
}
